from math import gcd

def min_operations_to_one(a):
    n = len(a)
    total_ops = 0

    while True:
        max_val = max(a)
        if max_val == 1:
            return total_ops

        found_pair = False
        for i in range(1, n):
            if a[i] != a[0]:
                continue
            found_pair = True
            break

        if not found_pair:
            return -1

        current_gcd = a[0]
        indices = []
        for i in range(n):
            if a[i] % current_gcd != 0:
                continue
            indices.append(i)

        if len(indices) == 1:
            return -1

        smallest_index = indices[0]
        for index in indices[1:]:
            current_gcd = gcd(current_gcd, a[index])
            if current_gcd == 1:
                smallest_index = index
                break

        a[smallest_index] //= gcd(a[smallest_index], a[(smallest_index + 1) % n])
        total_ops += 1

